/**
 * 首页 - whaleal.com 主站
 *
 * 多语言：文案全部来自 i18n/dictionaries/home.js，本文件**只保留布局与品牌常量引用**。
 * 🔴 加语言只改字典，不碰本文件 —— 布局改动风险最高（构建只能靠 CI 验证），
 *    把可翻译文案挪出 JSX 后，翻译不再有碰坏布局的机会。
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import ProductVideo from '../components/ProductVideo';
import ProductCardGallery from '../components/ProductCardGallery';
import FreeInstallCta from '../components/FreeInstallCta';
import { usePageI18n } from '../i18n';
import homeCopy from '../i18n/dictionaries/home';
import {
  PRODUCT_NAME_FULL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_INSTALL_PAGE_PATH,
  CART_VIDEO_OVERVIEW_30S,
  CART_PRODUCT_CARDS,
} from '../constants/brand';
import './index.css';

export default function HomePage({ pageContext }) {
  const { locale, localePath, page } = usePageI18n(pageContext);
  const c = homeCopy[locale] || homeCopy.en;
  // 🔴 SEO 文案必须走 i18n/dictionaries/pages.js，**不能硬编码英文**：
  //    否则 /de/、/fr/ 的 <title>/<meta description> 与英文页一字不差，
  //    搜索引擎拿不到任何「这是德语/法语页面」的信号（hreflang 全白给）。
  const meta = page.home;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={meta.metaTitle}
        description={meta.metaDescription}
        pathname="/"
        hrefLang={locale}
      />
      <div className="homepage">
        <div className="homepage-hero">
          <div className="homepage-badge">
            <span className="homepage-badge-icon">🛍️</span>
            {c.badge}
          </div>
          <h1>{c.h1}</h1>
          <p className="homepage-description">
            <strong>{PRODUCT_NAME_FULL}</strong> {c.leadTop} {c.leadRest}
          </p>
          <div className="homepage-actions homepage-actions-hero">
            <Link to={localePath(SHOPIFY_INSTALL_PAGE_PATH)} className="homepage-button homepage-button-primary">
              {c.ctaPrimary}
            </Link>
            <a
              href={SHOPIFY_APP_STORE_URL}
              className="homepage-button homepage-button-secondary"
              target="_blank"
              rel="noopener noreferrer"
            >
              {c.ctaSecondary}
            </a>
            <Link to={localePath('/pricing/')} className="homepage-hero-text-link">
              {c.ctaPricing}
            </Link>
          </div>
          <p className="homepage-hero-micro">{c.micro}</p>
        </div>

        <section className="homepage-section homepage-product">
          <div className="homepage-product-header">
            <span className="homepage-product-label">{c.productLabel}</span>
            <h2>{PRODUCT_NAME_FULL}</h2>
            <p className="homepage-section-lead">{c.productLead}</p>
          </div>
          <ProductVideo
            src={CART_VIDEO_OVERVIEW_30S.src}
            poster={CART_VIDEO_OVERVIEW_30S.poster}
            title={CART_VIDEO_OVERVIEW_30S.title}
            durationLabel={CART_VIDEO_OVERVIEW_30S.durationLabel}
          />
          <ProductCardGallery cards={CART_PRODUCT_CARDS} autoPlay intervalMs={4000} />
        </section>

        <section className="homepage-section homepage-problem">
          <h2>{c.problemTitle}</h2>
          <p className="homepage-section-lead">{c.problemLead}</p>
          <div className="homepage-stats">
            <div className="homepage-stat">
              <strong>{c.stat1Num}</strong>
              <span>{c.stat1Text}</span>
            </div>
            <div className="homepage-stat">
              <strong>{c.stat2Num}</strong>
              <span>{c.stat2Text}</span>
            </div>
            <div className="homepage-stat">
              <strong>{c.stat3Num}</strong>
              <span>{c.stat3Text}</span>
            </div>
          </div>
        </section>

        <section className="homepage-section homepage-features-section">
          <h2>{c.featuresTitle}</h2>
          <div className="homepage-features homepage-features-core">
            <div className="feature-card">
              <div className="feature-icon">📧</div>
              <h3>{c.f1Title}</h3>
              <p>{c.f1Text}</p>
              <Link to={localePath('/help/')} className="feature-card-link">
                {c.f1Link}
              </Link>
            </div>
            <div className="feature-card feature-card-highlight">
              <div className="feature-icon">🤖</div>
              <h3>{c.f2Title}</h3>
              <p>{c.f2Text}</p>
              <span className="feature-card-tier">{c.f2Tier}</span>
              <Link to={localePath('/features/ai-email-engine/')} className="feature-card-link">
                {c.f2Link}
              </Link>
            </div>
            <div className="feature-card">
              <div className="feature-icon">📱</div>
              <h3>{c.f3Title}</h3>
              <p>{c.f3Text}</p>
              <a
                href="https://sms.whaleal.com"
                className="feature-card-link"
                target="_blank"
                rel="noopener noreferrer"
              >
                {c.f3Link}
              </a>
            </div>
            <div className="feature-card">
              <div className="feature-icon">🎫</div>
              <h3>{c.f4Title}</h3>
              <p>{c.f4Text}</p>
              <Link to={localePath('/pricing/')} className="feature-card-link">
                {c.f4Link}
              </Link>
            </div>
          </div>
        </section>

        <section className="homepage-section homepage-how">
          <h2>{c.howTitle}</h2>
          <p className="homepage-section-lead">{c.howLead}</p>
          <div className="homepage-steps">
            <div className="homepage-step">
              <div className="homepage-step-num">1</div>
              <h3>{c.step1Title}</h3>
              <p>{c.step1Text}</p>
            </div>
            <div className="homepage-step">
              <div className="homepage-step-num">2</div>
              <h3>{c.step2Title}</h3>
              <p>{c.step2Text}</p>
            </div>
            <div className="homepage-step">
              <div className="homepage-step-num">3</div>
              <h3>{c.step3Title}</h3>
              <p>{c.step3Text}</p>
            </div>
          </div>
          <p className="homepage-how-more">
            <Link to={localePath('/help/')} className="homepage-inline-link-dark">
              {c.howMore}
            </Link>
          </p>
        </section>

        <section className="homepage-section homepage-free-cta">
          <FreeInstallCta variant="banner" title={c.finalTitle} />
        </section>

        <section className="homepage-section homepage-proof">
          <h2>{c.proofTitle}</h2>
          <div className="homepage-proof-grid">
            <div className="homepage-proof-card">
              <span className="homepage-product-label">{c.proof1Label}</span>
              <p>
                {c.proof1Text} <strong>{c.proof1Strong1}</strong> and{' '}
                <strong>{c.proof1Strong2}</strong> {c.proof1Text2}
              </p>
              <Link to={localePath('/customers/')} className="homepage-inline-link-dark">
                {c.proof1Link}
              </Link>
            </div>
            <div className="homepage-proof-card">
              <span className="homepage-product-label">{c.proof2Label}</span>
              <p>{c.proof2Text}</p>
              <a
                href={SHOPIFY_APP_STORE_URL}
                className="homepage-inline-link-dark"
                target="_blank"
                rel="noopener noreferrer"
              >
                {SHOPIFY_APP_STORE_LABEL} →
              </a>
            </div>
          </div>
        </section>

        <div className="homepage-cta">
          <h2>{c.finalTitle}</h2>
          <p>{c.finalLead}</p>
          <div className="homepage-actions">
            <Link to={localePath(SHOPIFY_INSTALL_PAGE_PATH)} className="homepage-button homepage-button-primary">
              {c.finalCtaPrimary}
            </Link>
            <a
              href={SHOPIFY_APP_STORE_URL}
              className="homepage-button homepage-button-secondary"
              target="_blank"
              rel="noopener noreferrer"
            >
              {c.finalCtaSecondary}
            </a>
          </div>
        </div>
      </div>
    </Layout>
  );
}